import React, { useState, useEffect } from 'react';
import Card from '../components/Card';
import deepData from '../data/deep-end.json';

const Game = ({ modeId = 'deep' }) => {
  const [questions, setQuestions] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAnimating, setIsAnimating] = useState(false);

  // Inicializa e baralha as perguntas
  useEffect(() => {
    const allQuestions = deepData.categories.flatMap(cat => 
      cat.questions.map(q => ({ text: q, category: cat.title }))
    );
    setQuestions(allQuestions.sort(() => Math.random() - 0.5));
  }, [modeId]);

  const nextQuestion = () => {
    if (isAnimating) return;
    setIsAnimating(true);
    
    setTimeout(() => {
      setCurrentIndex((prev) => (prev + 1) % questions.length);
      setIsAnimating(false);
    }, 300);
  };

  if (questions.length === 0) return <div className="bg-raw-onyx min-h-screen" />;

  return (
    <div className="min-h-screen bg-raw-onyx flex flex-col items-center justify-center p-6 overflow-hidden">
      {/* HUD de Progresso / Incandescência */}
      <div className="fixed top-10 w-full max-w-md px-10">
        <div className="flex justify-between text-[10px] text-raw-bone/40 uppercase tracking-widest mb-2">
          <span>Nível de Incandescência</span>
          <span>{currentIndex + 1} / {questions.length}</span>
        </div>
        <div className="h-1 bg-raw-bone/10 w-full">
          <div 
            className="h-full bg-raw-cyan shadow-[0_0_15px_rgba(0,240,255,0.8)] transition-all duration-500"
            style={{ width: `${((currentIndex + 1) / questions.length) * 100}%` }}
          />
        </div>
      </div>

      {/* Área do Cartão */}
      <div 
        onClick={nextQuestion}
        className={`cursor-pointer transition-all duration-300 transform ${
          isAnimating ? 'scale-95 opacity-0 rotate-3' : 'scale-100 opacity-100 rotate-0'
        }`}
      >
        <Card 
          text={questions[currentIndex].text} 
          category={questions[currentIndex].category} 
        />
      </div>

      {/* Controlos de Rodapé */}
      <div className="mt-16 flex flex-col items-center">
        <button 
          onClick={nextQuestion}
          className="text-raw-bone font-archivo text-xs uppercase tracking-[0.4em] border-b border-raw-cyan pb-2 hover:text-raw-cyan transition-colors"
        >
          Toca para Próxima
        </button>
        
        <div className="mt-8 opacity-20 hover:opacity-100 transition-opacity">
           <a href="https://github.com/16alves02" className="text-[10px] text-raw-bone uppercase font-inter tracking-widest">
             Dev by @16alves02
           </a>
        </div>
      </div>
    </div>
  );
};

export default Game;
